const competitionKinds=['Liga','Taça','Supertaça','Continental','Internacional','Outro'];
const competitionFormats=['Liga','Eliminatórias','Grupos + eliminatórias','Misto','Outro'];
function competitionEngineMode(c){return c.id===0||c.id===1?'league':(c.engineMode||'catalogue');}
const competitionEngineLabels={league:'Liga simulada',cup:'Taça jogável',feeder:'Liga de acesso',catalogue:'Catálogo / futuro'};
function competitionMark(c,key='logo'){
 const src=c?.[key];
 if(src)return `<span class="competition-image ${key==='trophy'?'trophy':''}"><img src="${esc(src)}" alt="${key==='trophy'?'Troféu':'Logótipo'} de ${esc(c.name)}"></span>`;
 const initials=(c?.shortName||c?.name||'?').split(/\s+/).map(x=>x[0]).join('').slice(0,3).toUpperCase();
 return `<span class="competition-image ${key==='trophy'?'trophy':''} placeholder">${esc(key==='trophy'?'🏆':initials)}</span>`;
}
function competitionParticipants(c,state=master){
 const mode=competitionEngineMode(c);if(mode==='league')return state.clubs.filter(x=>x.div===c.id).map(x=>x.id);if(mode==='feeder')return state.clubs.filter(x=>x.div===2).map(x=>x.id);
 return Array.isArray(c.participants)?c.participants:[];
}
function competitionStatus(c){const mode=competitionEngineMode(c);return mode==='league'?'SIMULADA NO MATCH ENGINE':mode==='cup'?'TAÇA JOGÁVEL':mode==='feeder'?'LIGA DE ACESSO À CHALLENGE':'REGISTADA · MOTOR FUTURO';}
function setupCompetitionMedia(form,draft,key,label){
 const input=form.querySelector(`[data-competition-file="${key}"]`),preview=form.querySelector(`[data-competition-preview="${key}"]`),remove=form.querySelector(`[data-competition-remove="${key}"]`),error=form.querySelector('.competition-error'),submit=form.querySelector('[type="submit"]');
 const draw=()=>{preview.innerHTML=draft[key]?`<img src="${esc(draft[key])}" alt="${esc(label)}">`:`<span>Sem ${esc(label.toLowerCase())}</span>`;};draw();
 let request=0;
 input.onchange=async e=>{const file=e.target.files[0];if(!file)return;const token=++request;submit.disabled=true;error.textContent=`A preparar ${label.toLowerCase()}…`;try{const data=await readClubLogo(file);if(token!==request)return;draft[key]=data;draw();error.textContent='';}catch(err){if(token===request)error.textContent=`Não foi possível abrir ${label.toLowerCase()}. ${err.message||''}`;}finally{if(token===request)submit.disabled=false;}};
 remove.onclick=()=>{request++;draft[key]='';input.value='';draw();error.textContent='';submit.disabled=false;};
}
function renderCompetitionForm(c){
 const mode=competitionEngineMode(c),participants=competitionParticipants(c),protectedCompetition=[0,1,2,3].includes(c.id),derivedParticipants=['league','feeder'].includes(mode);
 const participantHtml=derivedParticipants?`<div class="competition-participant-summary"><b>${participants.length} clubes ligados ao escalão</b><span>${master.clubs.filter(x=>participants.includes(x.id)).map(x=>esc(x.name)).join(' · ')}</span></div>`:`<div class="competition-participants">${master.clubs.map(cl=>`<label><input type="checkbox" name="participants" value="${cl.id}" ${participants.includes(cl.id)?'checked':''}> ${esc(cl.name)}</label>`).join('')}</div>`;
 const engineSelect=protectedCompetition?`<label>Motor<input value="${esc(competitionEngineLabels[mode]||mode)}" disabled></label>`:`<label>Motor<select name="engineMode"><option value="catalogue" ${mode==='catalogue'?'selected':''}>Catálogo / futuro</option><option value="cup" ${mode==='cup'?'selected':''}>Taça eliminatória jogável</option></select></label>`;
 const official=c.officialName?`<label>Nome oficial<input name="officialName" maxlength="100" value="${esc(c.officialName)}"></label>`:'';
 const engineText=mode==='league'?'Alimenta o calendário, classificação e promoção/despromoção das duas ligas profissionais.':mode==='feeder'?'Os clubes deste escalão formam a bolsa real de promoção à Challenge League. Equipas U-21 podem estar presentes, mas não sobem.':mode==='cup'?'O motor gera eliminatórias, prolongamento e desempate por penáltis. A Taça da Suíça usa as regras e a 1.ª ronda oficial de 2026/27 incluídas na base.':'A competição fica documentada na base, mas não gera jogos enquanto estiver em modo catálogo.';
 return `<section class="panel competition-card" data-competition-card="${c.id}"><div class="competition-card-head"><div class="competition-identity">${competitionMark(c)}<div><span class="eyebrow">${esc(competitionStatus(c))}</span><h2>${esc(c.name)}</h2><p class="muted">ID ${c.id}${c.level?` · Nível ${c.level}`:''} · ${esc(c.kind||'Liga')} · ${esc(c.format||'Liga')}</p></div></div>${competitionMark(c,'trophy')}</div><form data-competition="${c.id}"><div class="player-grid"><label>Nome<input name="name" maxlength="100" required value="${esc(c.name)}"></label>${official}<label>Nome curto<input name="shortName" maxlength="50" value="${esc(c.shortName||'')}"></label><label>País / território<input name="country" maxlength="100" required value="${esc(c.country||'Suíça')}"></label><label>Tipo<select name="kind">${options(competitionKinds,c.kind||'Liga')}</select></label><label>Formato<select name="format">${options(competitionFormats,c.format||'Liga')}</select></label><label>Nível / escalão<input name="level" type="number" min="1" max="100" value="${c.level??''}" placeholder="Opcional"></label>${engineSelect}</div><div class="competition-engine-note"><b>${esc(competitionEngineLabels[mode]||mode)}</b><span>${esc(engineText)}</span></div>${mode==='league'?`<h3>Pontuação</h3><div class="player-grid"><label>Pontos por vitória<input name="pointsWin" type="number" min="0" max="10" required value="${c.pointsWin}"></label><label>Pontos por empate<input name="pointsDraw" type="number" min="0" max="10" required value="${c.pointsDraw}"></label><label>Pontos por derrota<input name="pointsLoss" type="number" min="0" max="10" required value="${c.pointsLoss}"></label></div>`:'<input type="hidden" name="pointsWin" value="3"><input type="hidden" name="pointsDraw" value="1"><input type="hidden" name="pointsLoss" value="0">'}<h3>Participantes</h3>${participantHtml}${mode==='cup'?`<p class="muted">Para taças criadas por ti, usa 2, 4, 8, 16, 32, 64… participantes. O motor cria as eliminatórias automaticamente.</p>`:''}<h3>Identidade visual</h3><div class="competition-media-grid"><div class="competition-media-editor"><label>Logótipo da competição<input data-competition-file="logo" type="file" accept="image/*,.bmp,.dib,.ico,.avif,.svg"></label><div class="competition-media-preview" data-competition-preview="logo"></div><button type="button" data-competition-remove="logo">Remover logótipo</button></div><div class="competition-media-editor"><label>Imagem do troféu<input data-competition-file="trophy" type="file" accept="image/*,.bmp,.dib,.ico,.avif,.svg"></label><div class="competition-media-preview trophy" data-competition-preview="trophy"></div><button type="button" data-competition-remove="trophy">Remover troféu</button></div></div><p class="muted">As imagens são optimizadas automaticamente, preservando a transparência, e incluídas no ficheiro da Base de Dados Mestre.</p><label>Notas<textarea name="notes" maxlength="5000">${esc(c.notes||'')}</textarea></label><div class="competition-actions"><span class="competition-error" role="alert"></span>${protectedCompetition?'':`<button type="button" class="danger" data-delete-competition="${c.id}">Eliminar competição</button>`}<button type="submit" class="primary">Guardar competição</button></div></form></section>`;
}
function addCompetition(){
 const nextId=Math.max(1,...master.competitions.map(c=>c.id))+1;
 const record={id:nextId,name:'Nova competição',shortName:'',country:'Suíça',kind:'Taça',format:'Eliminatórias',engineMode:'catalogue',pointsWin:3,pointsDraw:1,pointsLoss:0,participants:[],notes:'',logo:'',trophy:''};
 const candidate={...master,competitions:[...master.competitions,record]};
 try{World.validate(candidate);master=candidate;s=World.context(master);render();message('Nova competição criada na sessão. Edita os dados e guarda a Base Mestre quando estiveres satisfeito.');setTimeout(()=>document.querySelector(`[data-competition-card="${nextId}"]`)?.scrollIntoView({behavior:'smooth',block:'start'}),0);}catch(err){message(err.message);}
}
function deleteCompetition(id){
 const c=master.competitions.find(x=>x.id===id);if(!c||id<2)return;if(!confirm(`Eliminar “${c.name}” da Base de Dados Mestre?`))return;
 const candidate={...master,competitions:master.competitions.filter(x=>x.id!==id)};
 try{World.validate(candidate);master=candidate;s=World.context(master);render();message('Competição eliminada da sessão.');}catch(err){message(err.message);}
}
function renderCompetitionsEditor(){
 $('app').innerHTML=`<div class="database-banner"><b>Editor de competições</b><br>As ligas profissionais, a Taça da Suíça e a Promotion League já têm funções próprias no motor. Podes ainda criar competições de catálogo ou novas taças eliminatórias jogáveis, com participantes, logótipo e troféu.</div><div class="toolbar"><button id="addCompetition" class="primary">+ Criar competição</button><span class="muted">${master.competitions.length} competições registadas</span></div><div class="competition-list">${master.competitions.map(renderCompetitionForm).join('')}</div><section class="panel" style="margin-top:20px"><h2>Distribuição inicial das ligas</h2><p class="muted">Mantemos 12 clubes na Super League e 10 na Challenge League. A Promotion League contém ${master.clubs.filter(c=>c.div===2).length} clubes adicionais e alimenta a subida ao segundo escalão. Aqui podes trocar apenas os dois escalões profissionais.</p><form id="divisionSwap" class="toolbar">${[0,1].map(d=>`<label>${esc(Engine.competition(s,d).name)}<select name="division${d}">${master.clubs.filter(c=>c.div===d).map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label>`).join('')}<button type="submit">Trocar divisões</button></form><p id="swapError" role="alert"></p></section>`;
 $('addCompetition').onclick=addCompetition;
 document.querySelectorAll('[data-competition]').forEach(form=>{
  const id=+form.dataset.competition,c=master.competitions.find(x=>x.id===id),draft=structuredClone(c);form._competitionDraft=draft;setupCompetitionMedia(form,draft,'logo','Logótipo');setupCompetitionMedia(form,draft,'trophy','Troféu');
  form.onsubmit=e=>{e.preventDefault();const f=new FormData(form),fixed=[0,1,2,3].includes(id),mode=fixed?competitionEngineMode(c):String(f.get('engineMode')||'catalogue'),record={...draft,name:String(f.get('name')).trim(),shortName:String(f.get('shortName')||'').trim(),country:String(f.get('country')).trim(),kind:String(f.get('kind')),format:String(f.get('format')),pointsWin:+f.get('pointsWin'),pointsDraw:+f.get('pointsDraw'),pointsLoss:+f.get('pointsLoss'),notes:String(f.get('notes')||'').trim(),engineMode:mode};if(f.has('officialName'))record.officialName=String(f.get('officialName')||'').trim();const level=f.get('level');if(level==='')delete record.level;else record.level=+level;if(['catalogue','cup'].includes(mode))record.participants=f.getAll('participants').map(Number);else delete record.participants;if(mode==='cup'&&!record.roundNames)record.roundNames=[];const candidate={...master,competitions:master.competitions.map(x=>x.id===id?record:x)};try{World.validate(candidate);master=candidate;s=World.context(master);render();message(editorSaveMessage());}catch(err){form.querySelector('.competition-error').textContent=err.message;}};
 });
 document.querySelectorAll('[data-delete-competition]').forEach(b=>b.onclick=()=>deleteCompetition(+b.dataset.deleteCompetition));
 $('divisionSwap').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target);try{World.swapDivisions(master,+data.get('division0'),+data.get('division1'));s=World.context(master);render();message(editorSaveMessage());}catch(err){$('swapError').textContent=err.message;}};
}
